/// Discussion Board Notification - This implements the notification delivery and alerting requirement from the requirements documents (particularly 03_discussionboard_features_and_functional_specifications.md, section 7 Notifications and Alerts; see also user journeys and business rules). 
///
/// Business explanation: Stores detailed notifications generated by the system—such as mentions, replies, moderator actions, and administrative announcements—to be delivered to specific users. Ensures users are promptly informed of activity requiring their attention. Maintains full 3NF compliance: notification text, type, and linkage to recipient are atomic and non-redundant. For example, when a user is mentioned in a comment, a notification is created here detailing the context and recipient. 
///
/// Key relationships: References discussionboard_members as notification recipient; may also reference other entities (e.g., post/thread) as optional context if needed (not included here, but ID pattern allows for future extension). 
/// Special behaviors: Soft deletion via nullable deleted_at; status/opened flag; delivery details and related timestamps for auditability and analytics; all notifications are individualized and immutable after creation. Audit trails of delivery status handled within this model.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_notifications {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each notification record. Ensures entity uniqueness and supports distributed environments. Required for all entities for tracking and referencing.
  id String @id @db.Uuid

  /// Recipient's {@link discussionboard_members.id}. Indicates which member this notification is intended for. Enables delivery targeting and audit trail. Required for all notifications.
  discussionboard_member_id String @db.Uuid

  /// Notification type - Implements requirement for distinguishing system, user, moderation, and announcement notifications. Possible values: 'mention', 'reply', 'moderator_action', 'announcement', etc. Ensures clear categorization for UI badge and analytics. Example: When a thread is locked, moderators receive a 'moderator_action' type notification. Atomic and fully normalized.
  type String

  /// Notification title or brief summary - Implements clear communication of subject as required by UX guidelines. Summarizes notification content in a single line for user display. Example: 'You were mentioned in a post.' Fully normalized.
  title String

  /// Full textual content of the notification - Implements rich, readable notification context as required by the user journey and business rules. Contains detailed context such as source thread or action taken. Example: 'Your post in "2025 Elections Economy" was edited by a moderator.'
  body String?

  /// Optional URI to direct recipient to the notification context. Supports quick navigation to relevant thread, post, or profile. Implements UX quick-access requirement. Example: '/thread/abc123/post/xyz456'.
  url String? @db.VarChar(80000)

  /// Whether the notification has been opened/read by the recipient - Implements user status tracking for badge counts & UX feedback. Example: New notifications are false; becomes true when user visits notification center or clicks link. Fully normalized with no redundant status.
  opened Boolean

  /// Notification creation timestamp. Implements requirement to log when notifications are generated, for both UX ordering and audit trails. Non-nullable for history and analytics purposes.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the notification was opened/read. Enables precise auditing and user interaction analytics. Nullable for unopened notifications. Ensures atomic status-tracking in 3NF structure.
  opened_at DateTime? @db.Timestamptz

