  expires_at DateTime @db.Timestamptz

  /// Timestamp of the last activity on this session. Implements last-used tracking for security checks (token expiration, forced logout). For example, updated on each page load or action.
  last_activity_at DateTime? @db.Timestamptz

  /// Time at which session was revoked, if applicable. Implements security and forced logout. For example, set if session is invalidated by admin or system.
  revoked_at DateTime? @db.Timestamptz

  /// IP address recorded when session was initiated. Provides security auditing for login source and supports fraud monitoring. For example, '192.168.1.1'.
  ip_address String?

