schemas.schema-03-threads_posts.prisma:
/// Thread Root Entity - This implements the 'thread management and creation' requirement from the features and user journeys documentation. Each instance represents an individual discussion thread (topic) started by a member, with links to category/section and root post. Maintains 3NF compliance by separating main thread data (title, status, author/member, section/category) from posts, histories, and related engagement. For example, a new thread '2025 Elections Discussion' would have one record here and many related post/comment records elsewhere. 
/// Key relationships: Links to author member, category, and root post via foreign keys. Special behaviors: Soft-deletion (archived flag), per-thread lock/pin status for moderation/admins.
///
/// @namespace ThreadsPosts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_threads {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique thread identifier.
  id String @id @db.Uuid

  /// Thread author's {@link discussionboard_members.id}. Refers to the member who created the thread.
  discussionboard_member_id String @db.Uuid

  /// Thread's assigned {@link discussionboard_categories.id}. Refers to the topic/category under which this thread is created.
  discussionboard_category_id String @db.Uuid

  /// Thread title - Implements the required summary/title as per requirements document. Atomic, and always present. For example: '2025 Economic Outlook'.
  title String

  /// Thread status - Active, archived, locked. Implements moderation control requirement. For example: 'active', 'locked', 'archived'.
  status String

  /// Pinned flag - Whether this thread is pinned at the top. Implements thread management feature for moderators/admins. true if pinned by moderation.
  is_pinned Boolean

  /// Locked flag - Whether this thread is locked. Implements moderation tool for controlling participation. true if thread no longer accepts replies.
  is_locked Boolean

  /// Soft delete/archive flag. If true, thread is hidden from public but data is retained for admins/audit. Implements audit/compliance rules.
  archived Boolean

  /// Thread creation timestamp. For audit/logging as per business rules.
  created_at DateTime @db.Timestamptz

  /// Thread last updated timestamp. Updated on edits or moderation events. Required for audit trail and UX.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  member   discussionboard_members    @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)
  category discussionboard_categories @relation(fields: [discussionboard_category_id], references: [id], onDelete: Cascade)

  discussionboard_posts           discussionboard_posts[]
  discussionboard_thread_archives discussionboard_thread_archives[]
  discussionboard_polls           discussionboard_polls[]
  discussionboard_tagged_threads  discussionboard_tagged_threads[]

  @@unique([title, discussionboard_category_id])
  @@index([discussionboard_category_id])
  @@index([discussionboard_member_id, created_at], map: "discussionboard_threads_discussionboard_member_id_crea_978c1236")
  @@index([status])
  @@index([is_pinned, is_locked])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Thread Post Entity - Implements the 'thread and comment posting', 'reply', and 'content moderation/reporting' features. Each represents an individual post or comment in a thread, with parent-child relation for comments (nested structure). Maintains 3NF compliance by keeping each post atomic and referring to its thread, author, and parent. For example, a threaded reply is a record here with a parent post. Key relationships: thread linkage, post author (member), optional parent for comments. Special behaviors: supports nested replies, soft deletion.
///
