schemas.schema-04-moderation.prisma:
/// Content Report Entity - This implements the requirement for capturing and tracking user-reported content as defined in 'Business Rules and Policies' and across 'Features and Functional Specifications'.
///
/// This model records when a member or guest files a report on a post, comment, or thread for policy violations, harassment, or inappropriate content. It maintains normalized structure (3NF) by capturing report details and referencing the post/content in violation, along with the reporting user and reason. For example, when a member reports a post they believe is a violation, a new row is created here and linked to the moderation review process.
///
/// Key relationships: References reporter (member or guest by user_id/actor_id) and the offending content (from the threads/posts tables in the ThreadsPosts component).
/// Special behaviors: Maintains audit trail; supports escalation workflow and status updates.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_content_reports {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each content report entry.
  id String @id @db.Uuid

  /// Target post's {@link discussionboard_posts.id} reported for violation or moderation. May also be used to reference a comment if required.
  reported_post_id String @db.Uuid

  /// Reporting member's {@link discussionboard_members.id}, if the reporter is a registered member.
  reporter_member_id String? @db.Uuid

  /// Reporting guest's {@link discussionboard_guests.id}, if the report was filed by a guest user (optional).
  reporter_guest_id String? @db.Uuid

  /// Reason for content report - Implements requirement to capture user's motivation for reporting content. Ensures normalization by storing only reason text; examples include 'spam', 'abuse', 'off-topic', etc. Required for moderation triage and analytics.
  report_reason String

  /// Moderation status of the report - Implements status tracking for the moderation queue. Allowed values are 'pending', 'in_review', 'action_taken', 'dismissed', reflecting different workflow states. Ensures normalization by storing only the status token. For example, 'pending' is assigned on creation.
  status String

  /// Timestamp when the content was reported - Implements audit trail requirement and ensures detailed moderation history. Not nullable.
  reported_at DateTime @db.Timestamptz

  /// Moderator's note on review outcome - Allows documenting justification for resolution or further actions. Nullable; present after moderator review.
  moderator_note String?

  //----
  // RELATIONS
  //----
  fk_content_reports_post   discussionboard_posts    @relation(fields: [reported_post_id], references: [id], onDelete: Cascade)
  fk_content_reports_member discussionboard_members? @relation(fields: [reporter_member_id], references: [id], onDelete: Cascade)
  fk_content_reports_guest  discussionboard_guests?  @relation(fields: [reporter_guest_id], references: [id], onDelete: Cascade)

  discussionboard_moderation_actions discussionboard_moderation_actions[]

  @@index([reporter_guest_id])
  @@index([reported_post_id])
  @@index([reporter_member_id])
  @@index([report_reason, status])
  @@index([report_reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Moderation Action Entity - Implements requirement for logging all actions taken by moderators or admins in response to reports, violations, or escalations as described in 'Features and Functional Specifications' and 'Business Rules and Policies'.
///
/// This model records every action taken during moderation (warning issued, thread locked, post deleted, user suspended, etc.), who performed it, and on which content or user. Maintains 3NF by linking actions to actors (moderator/admin), target content or users, and report IDs if applicable. E.g., When a moderator deletes a post for policy violation, this logs the event with details.
///
/// Key relationships: Relates to moderation actor, affected user (optional), and reported content. Also links to the report if action was a result of a report.
/// Special behaviors: Immutable audit log for compliance and appeals.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_moderation_actions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each moderation action.
  id String @id @db.Uuid

  /// Actor's {@link discussionboard_moderators.id} who performed the action. Required for accountability.
  moderator_id String @db.Uuid

