  affected_member_id String? @db.Uuid

  /// Type of moderation action taken - Implements audit trail and compliance requirements. Examples: 'warned', 'deleted_post', 'suspended_user', 'locked_thread', 'archived_thread'. Only atomic state; details are in the description. Keeps the table normalized. For example, 'warned' or 'deleted_post'.
  action_type String

  /// Detailed description for the action - Implements need for justification and appeals. Ensures normalization by keeping only description in text. E.g., 'Post contained prohibited content per rule X.'
  action_description String

